 public static void main(String[] args){try{android.os.Looper.prepareMainLooper();Class<?> threadClass=Class.forName("android.app.ActivityThread");Object thread=threadClass.getMethod("systemMain").invoke(null);android.content.Context context=(android.content.Context)threadClass.getMethod("getSystemContext").invoke(thread);context=context.createPackageContext("com.picviewer.app",0);android.app.Application app=new android.app.Application();java.lang.reflect.Method attach=android.app.Application.class.getDeclaredMethod("attach",android.content.Context.class);attach.setAccessible(true);attach.invoke(app,context);java.lang.reflect.Field field=threadClass.getDeclaredField("mInitialApplication");field.setAccessible(true);field.set(thread,app);Class.forName("android.security.keystore.AndroidKeyStoreProvider").getMethod("install").invoke(null);String text="synthetic-keystore-fixture-not-an-account-password";String a=Config.crypt(true,text),b=Config.crypt(true,text);if(a.equals(b))throw new AssertionError("GCM IV reuse");if(!text.equals(Config.crypt(false,a))||!text.equals(Config.crypt(false,b)))throw new AssertionError("roundtrip");String[] parts=a.split(":",2);byte[] ciphertext=android.util.Base64.decode(parts[1],android.util.Base64.NO_WRAP);ciphertext[0]^=1;boolean rejected=false;try{Config.crypt(false,parts[0]+":"+android.util.Base64.encodeToString(ciphertext,android.util.Base64.NO_WRAP));}catch(Exception expected){rejected=true;}if(!rejected)throw new AssertionError("tamper accepted");System.out.println("KEYSTORE_ROUNDTRIP_IV_AND_TAMPER_PASS");}catch(Throwable e){e.printStackTrace();System.exit(1);}}
